import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long q = nextLong();
        long[] a = new long[n], gaps = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) gaps[i] = Math.max(0, nextLong() - a[i]);
        Arrays.sort(gaps);
        int answer = 0;
        for (long gap : gaps) {
            if (gap > q) break;
            q -= gap;
            answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"sort"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, q := int(nextInt()), nextInt()
	a, gaps := make([]int64, n), make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	for i := range gaps {
		gaps[i] = max(0, nextInt()-a[i])
	}
	sort.Slice(gaps, func(i, j int) bool { return gaps[i] < gaps[j] })
	answer := 0
	for _, gap := range gaps {
		if gap > q {
			break
		}
		q -= gap
		answer++
	}
	w.WriteString(strconv.Itoa(answer) + "\n")
}
